/* services/repository.js — the in-browser "database" built from REAL_DATA (generated by etl/build_data.py).
   Standings, team totals and player totals are all aggregated from per-fixture records, so they reconcile
   with the official scores (the ETL verifies this). With a live backend each function maps to a SQL view. */

const REPO_CACHE = {};
const APP_KEYS = ['fi', 'pi', 'home', 'min', 'start', 'g', 'a', 'xg', 'xa', 'xgc', 'cs', 'gc', 'sv', 'psv', 'pm', 'og', 'yc', 'rc', 'bonus', 'bps', 'pts', 'inf', 'cre', 'thr', 'tk', 'cbi', 'rec', 'dc'];
const SUM_KEYS = ['min', 'start', 'g', 'a', 'xg', 'xa', 'xgc', 'cs', 'gc', 'sv', 'psv', 'pm', 'og', 'yc', 'rc', 'bonus', 'bps', 'pts', 'inf', 'cre', 'thr', 'tk', 'cbi', 'rec', 'dc'];
const r1 = v => Math.round(v * 10) / 10;
const r2 = v => Math.round(v * 100) / 100;

/* Kick-off times are UTC in the source; show them in UK time like the league does. */
const UK_DATE = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/London', year: 'numeric', month: '2-digit', day: '2-digit' });
const UK_TIME = new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/London', hour: '2-digit', minute: '2-digit', hour12: false });

/* Latest known identity for every person across seasons (name, position, birth date). */
const PEOPLE = {};
REAL_DATA.seasons.slice().reverse().forEach(s => s.players.forEach(([id, name, pos, birth, code]) => {
  PEOPLE[id] = { id, name, position: pos, birth: birth || (PEOPLE[id] && PEOPLE[id].birth) || null, code };
}));
const PLAYER_BY_ID = PEOPLE;

function ageAt(birth, year) {
  if (!birth) return null;
  const [y, m, d] = birth.split('-').map(Number);
  let age = year - y; if (m > 8 || (m === 8 && d > 1)) age--;   // age on 1 August of the season
  return age;
}
function emptyStats() { const o = { apps: 0, series: [] }; SUM_KEYS.forEach(k => { o[k] = 0; }); return o; }
function finishStats(a) {
  a.starts = a.start; delete a.start;
  a.xg = r2(a.xg / 100); a.xa = r2(a.xa / 100); a.xgc = r2(a.xgc / 100); a.xgi = r2(a.xg + a.xa);
  a.inf = r1(a.inf / 10); a.cre = r1(a.cre / 10); a.thr = r1(a.thr / 10); a.ict = r1((a.inf + a.cre + a.thr) / 10);
  a.ppg = a.apps ? r2(a.pts / a.apps) : null;
  return a;
}

function repo(seasonId) {
  if (REPO_CACHE[seasonId]) return REPO_CACHE[seasonId];
  const raw = REAL_DATA.seasons.find(s => s.id === seasonId);
  if (!raw) throw new Error(`Season ${seasonId} is not in the dataset.`);
  const season = SEASONS.find(s => s.id === seasonId);

  // ---- matches
  const matches = raw.fixtures.map(([fplId, gw, kickoff, home, away, hs, as]) => {
    const k = kickoff ? new Date(kickoff) : null;
    const done = hs != null;
    return {
      id: `${seasonId}-${String(gw).padStart(2, '0')}-${TEAM_BY_ID[home].short}-${TEAM_BY_ID[away].short}`.toLowerCase(), fplId,
      season: seasonId, matchweek: gw, kickoff, date: k ? UK_DATE.format(k) : null, time: k ? UK_TIME.format(k) : 'TBC',
      home, away, stadium: stadiumFor(TEAM_BY_ID[home], season.startYear), status: done ? 'finished' : 'scheduled',
      score: done ? { home: hs, away: as } : null, players: [],
    };
  });
  (raw.pendingStats || []).forEach(i => { matches[i].statsPending = true; });
  const cols = raw.matchStatCols || [];
  Object.entries(raw.matchStats || {}).forEach(([i, [h, a]]) => {
    const obj = arr => Object.fromEntries(cols.map((c, k) => [c, arr[k]]));
    matches[Number(i)].opta = { home: obj(h), away: obj(a) };   // team match stats (possession, shots, ...) where the source has them
  });
  const matchById = Object.fromEntries(matches.map(m => [m.id, m]));

  // ---- appearances -> match player rows, player totals (overall and per club)
  const pl = raw.players;
  const statsByPlayer = {}, statsByPlayerTeam = {};
  raw.apps.forEach(row => {
    const a = {}; APP_KEYS.forEach((k, i) => { a[k] = row[i]; });
    const m = matches[a.fi]; const pid = pl[a.pi][0]; const side = a.home ? 'home' : 'away'; const teamId = m[side];
    m.players.push({ pid, side, start: !!a.start, min: a.min, g: a.g, a: a.a, xg: a.xg / 100, xa: a.xa / 100, cs: a.cs, gc: a.gc, sv: a.sv, psv: a.psv, pm: a.pm, og: a.og, yc: a.yc, rc: a.rc, bonus: a.bonus, bps: a.bps, pts: a.pts, tk: a.tk, cbi: a.cbi });
    const pt = pid + '|' + teamId;
    if (!statsByPlayer[pid]) statsByPlayer[pid] = emptyStats();
    if (!statsByPlayerTeam[pt]) statsByPlayerTeam[pt] = emptyStats();
    [statsByPlayer[pid], statsByPlayerTeam[pt]].forEach(t => { t.apps++; SUM_KEYS.forEach(k => { t[k] += a[k]; }); });
    statsByPlayer[pid].series.push({ mw: m.matchweek, matchId: m.id, g: a.g, a: a.a, xg: a.xg / 100, pts: a.pts, min: a.min, sv: a.sv, cs: a.cs });
  });
  Object.values(statsByPlayer).forEach(finishStats); Object.values(statsByPlayerTeam).forEach(finishStats);

  // ---- team match stats (aggregated from player rows) + events
  const played = matches.filter(m => m.status === 'finished');
  played.forEach(m => {
    m.stats = {};
    ['home', 'away'].forEach(side => {
      const ps = m.players.filter(p => p.side === side);
      const sum = k => ps.reduce((t, p) => t + p[k], 0);
      m.stats[side] = { goals: m.score[side], xg: r2(sum('xg')), xa: r2(sum('xa')), saves: sum('sv'), yellow: sum('yc'), red: sum('rc'), bonus: sum('bonus'), tackles: sum('tk'), cbi: sum('cbi'), players: ps.length };
    });
    const ev = []; const oppSide = s => (s === 'home' ? 'away' : 'home');
    m.players.forEach(p => {
      if (p.g) ev.push({ type: 'goal', side: p.side, pid: p.pid, n: p.g });
      if (p.og) ev.push({ type: 'og', side: oppSide(p.side), pid: p.pid, n: p.og });
      if (p.a) ev.push({ type: 'assist', side: p.side, pid: p.pid, n: p.a });
      if (p.psv) ev.push({ type: 'pensave', side: p.side, pid: p.pid, n: p.psv });
      if (p.pm) ev.push({ type: 'penmiss', side: p.side, pid: p.pid, n: p.pm });
      if (p.yc) ev.push({ type: 'yellow', side: p.side, pid: p.pid, n: 1 });
      if (p.rc) ev.push({ type: 'red', side: p.side, pid: p.pid, n: 1 });
    });
    m.events = ev;
  });

  // ---- standings (points after each gameweek; postponed games count in the gameweek they were played)
  const table = {};
  raw.teams.forEach(t => { table[t] = { teamId: t, mp: 0, w: 0, d: 0, l: 0, gf: 0, ga: 0, pts: 0, results: [], xg: 0, xga: 0, cs: 0, pointsByWeek: [] }; });
  const byWeek = {}; played.forEach(m => { (byWeek[m.matchweek] = byWeek[m.matchweek] || []).push(m); });
  for (let w = 1; w <= season.playedWeeks; w++) {
    (byWeek[w] || []).forEach(m => {
      [['home', 'away'], ['away', 'home']].forEach(([s, o]) => {
        const row = table[m[s]]; const gf = m.score[s], ga = m.score[o];
        row.mp++; row.gf += gf; row.ga += ga; row.xg += m.stats[s].xg; row.xga += m.stats[o].xg;
        if (ga === 0) row.cs++;
        const res = gf > ga ? 'W' : gf === ga ? 'D' : 'L';
        row[res.toLowerCase()]++; row.pts += res === 'W' ? 3 : res === 'D' ? 1 : 0;
        row.results.push({ res, matchId: m.id, mw: w, opp: m[o], venue: s === 'home' ? 'H' : 'A', gf, ga, date: m.kickoff });
      });
    });
    raw.teams.forEach(t => table[t].pointsByWeek.push(table[t].pts));
  }
  Object.values(table).forEach(r => r.results.sort((a, b) => a.date.localeCompare(b.date)));
  const standings = Object.values(table).map(r => ({ ...r, gd: r.gf - r.ga, xg: r1(r.xg), xga: r1(r.xga), form: r.results.slice(-5).map(x => x.res) }))
    .sort((a, b) => b.pts - a.pts || b.gd - a.gd || b.gf - a.gf || TEAM_BY_ID[a.teamId].name.localeCompare(TEAM_BY_ID[b.teamId].name));
  standings.forEach((r, i) => { r.position = i + 1; r.zone = r.mp === 0 ? null : i < 4 ? 'ucl' : i < 6 ? 'uel' : i >= 17 ? 'rel' : null; });
  const standingByTeam = Object.fromEntries(standings.map(r => [r.teamId, r]));

  const teamStats = {};
  raw.teams.forEach(t => {
    const st = standingByTeam[t]; const ms = played.filter(m => m.home === t || m.away === t);
    const sum = k => ms.reduce((s, m) => s + m.stats[m.home === t ? 'home' : 'away'][k], 0);
    teamStats[t] = { goals: st.gf, conceded: st.ga, xg: st.xg, xga: st.xga, cleanSheets: st.cs, saves: sum('saves'), yellow: sum('yellow'), red: sum('red'), tackles: sum('tackles'), cbi: sum('cbi'), playersUsed: 0 };
  });

  // ---- players: club = latest club in the season; squad = everyone registered to the club during the season
  const memberships = raw.memberships.map(([pi, team, from, to]) => ({ pid: pl[pi][0], team, from, to }));
  const latestClub = {};
  memberships.forEach(m => { if (!latestClub[m.pid] || m.to >= latestClub[m.pid].to) latestClub[m.pid] = m; });
  // match-feed stats (FPL-Core-Insights, current season): merged into player stats with short keys
  const advCols = raw.advancedCols || [];
  const ADV_MAP = { distance_covered: 'dist', number_of_sprints: 'sprints', touches: 'touches', touches_opposition_box: 'tib', accurate_passes: 'accp', chances_created: 'cc',
    final_third_passes: 'f3', accurate_crosses: 'crosses', accurate_long_balls: 'longb', total_shots: 'shots', shots_on_target: 'sot', xgot: 'xgot', big_chances_missed: 'bcm',
    duels_won: 'duelsW', duels_lost: 'duelsL', ground_duels_won: 'gduels', aerial_duels_won: 'aduels', tackles_won: 'tkw', interceptions: 'int', blocks: 'blocks', clearances: 'clr',
    recoveries: 'recv', dribbled_past: 'dribPast', was_fouled: 'fouled', fouls_committed: 'fouls', dispossessed: 'disp', offsides: 'offs', xgot_faced: 'xgotF',
    goals_prevented: 'gp', sweeper_actions: 'sweep', high_claim: 'claims', saves_inside_box: 'svBox', top_speed: 'topSpeed', pass_pct: 'passPct', minutes_played: 'advMin', matches: 'advMatches' };
  const advOf = pid => {
    const row = raw.advanced && raw.advanced[pid]; if (!row) return null;
    const o = {}; advCols.forEach((c, i) => { if (ADV_MAP[c]) o[ADV_MAP[c]] = row[i]; });
    o.dist = r1(o.dist / 1000); o.duelPct = o.duelsW + o.duelsL ? r1(o.duelsW / (o.duelsW + o.duelsL) * 100) : null;
    return o;
  };
  const players = pl.map(([id, name, pos]) => ({
    id, name, position: pos, teamId: latestClub[id].team, age: ageAt(PEOPLE[id].birth, season.startYear), birth: PEOPLE[id].birth,
    photo: null, stats: Object.assign(statsByPlayer[id] || finishStats(emptyStats()), advOf(id) || {}),
  }));
  const playerById = Object.fromEntries(players.map(p => [p.id, p]));
  const squads = {};
  memberships.forEach(m => {
    const s = statsByPlayerTeam[m.pid + '|' + m.team] || finishStats(emptyStats());
    (squads[m.team] = squads[m.team] || []).push({ ...playerById[m.pid], teamId: m.team, stats: s, left: latestClub[m.pid].team !== m.team });
    if (s.apps) teamStats[m.team].playersUsed++;
  });

  REPO_CACHE[seasonId] = { season, raw, teams: raw.teams.slice(), matches, matchById, played, standings, standingByTeam, teamStats, players, playerById, squads, memberships };
  return REPO_CACHE[seasonId];
}

/* ---- transfers derived from squad data ----
   PL-to-PL moves are certain: a player is registered to club A last season and club B this season, or changes
   club mid-season. Arrivals from outside the league use FPL's team_join_date (available 2024/25 onwards). */
function derivedTransfers(seasonId) {
  const R = repo(seasonId); const idx = SEASONS.findIndex(s => s.id === seasonId); const prev = SEASONS[idx + 1] ? repo(SEASONS[idx + 1].id) : null;
  const out = [];
  const clubs = {};
  R.memberships.slice().sort((a, b) => a.from.localeCompare(b.from)).forEach(m => { (clubs[m.pid] = clubs[m.pid] || []).push(m); });
  const prevClub = {};
  if (prev) prev.memberships.forEach(m => { if (!prevClub[m.pid] || m.to >= prevClub[m.pid].to) prevClub[m.pid] = m; });
  const joins = Object.fromEntries((R.raw.joinDates || []).map(([pid, team, date]) => [pid + '|' + team, date]));
  const y = R.season.startYear;
  Object.entries(clubs).forEach(([pid, list]) => {
    list.forEach((m, i) => {
      const from = i > 0 ? list[i - 1].team : prevClub[pid] ? prevClub[pid].team : null;
      const join = joins[pid + '|' + m.team];
      if (from && from !== m.team) {
        out.push({ playerId: pid, playerName: PEOPLE[pid].name, from, to: m.team, date: join || m.from, midSeason: i > 0 });
      } else if (!from && join && join >= `${y}-05-15` && join <= `${y + 1}-02-15` && (!prev || !prev.playerById[pid])) {
        out.push({ playerId: pid, playerName: PEOPLE[pid].name, from: null, to: m.team, date: join, midSeason: join >= `${y}-12-15` });
      }
    });
  });
  out.forEach(t => { const f = reportedFee(seasonId, t.playerName, t.to); t.fee = f ? f.fee : undefined; });
  return out.sort((a, b) => (typeof b.fee === 'number' ? b.fee : -1) - (typeof a.fee === 'number' ? a.fee : -1) || b.date.localeCompare(a.date));
}

/* ---- radar / percentile helpers ---- */
function percentileScorer(pool, fn) {
  const vals = pool.map(fn).sort((a, b) => a - b);
  return v => {
    if (!vals.length) return 0;
    let lo = 0; while (lo < vals.length && vals[lo] < v) lo++;
    let hi = lo; while (hi < vals.length && vals[hi] === v) hi++;
    return Math.round(((lo + hi) / 2) / vals.length * 100);
  };
}
const per90 = (v, min) => (min > 0 ? v / min * 90 : 0);

function radarProfile(R, player) {
  const s = player.stats; const hasXg = R.season.hasXg; const maxMin = Math.max(1, R.season.playedWeeks * 90);
  const score = (pool, axes) => axes.map(([label, fn]) => ({ label, value: s.min ? percentileScorer(pool, fn)(fn(player)) : 0 }));
  if (player.position === 'GK') {
    const pool = R.players.filter(p => p.position === 'GK' && p.stats.min >= 450);
    const axes = [
      ['Saves', p => per90(p.stats.sv, p.stats.min)],
      ['Clean sheets', p => (p.stats.apps ? p.stats.cs / p.stats.apps : 0)],
      [hasXg ? 'Goals prevented' : 'Few conceded', p => (hasXg ? per90(p.stats.xgc - p.stats.gc, p.stats.min) : -per90(p.stats.gc, p.stats.min))],
      ['Influence', p => per90(p.stats.inf, p.stats.min)],
      ['Availability', p => p.stats.min / maxMin],
    ];
    return { note: 'Percentile vs Premier League goalkeepers with 450+ minutes', axes: score(pool, axes) };
  }
  const pool = R.players.filter(p => p.position !== 'GK' && p.stats.min >= 450);
  const axes = [
    ['Goal threat', p => per90(p.stats.thr, p.stats.min)],
    [hasXg ? 'xG' : 'Goals', p => per90(hasXg ? p.stats.xg : p.stats.g, p.stats.min)],
    ['Creativity', p => per90(p.stats.cre, p.stats.min)],
    [hasXg ? 'xA' : 'Assists', p => per90(hasXg ? p.stats.xa : p.stats.a, p.stats.min)],
    [R.season.hasDefensive ? 'Defensive actions' : 'Influence', p => per90(R.season.hasDefensive ? p.stats.dc : p.stats.inf, p.stats.min)],
    ['Availability', p => p.stats.min / maxMin],
  ];
  return { note: 'Percentile vs Premier League outfield players with 450+ minutes, per 90', axes: score(pool, axes) };
}

/* ---- team strength & fixture difficulty ----
   Strength = expected-goal difference per match over each club's most recent 38 league matches in the dataset
   (goal difference where xG is unavailable), shrunk towards a prior when a club has few matches:
   0 for established clubs, -0.5 for clubs with fewer than 10 recent matches (typically promoted sides). */
const HOME_ADV = 0.25;
function teamStrengths(seasonId) {
  const idx = SEASONS.findIndex(s => s.id === seasonId);
  const out = {};
  repo(seasonId).teams.forEach(t => {
    const vals = [];
    for (let i = idx; i < SEASONS.length && vals.length < 38; i++) {
      const R = repo(SEASONS[i].id); if (!R.teams.includes(t)) continue;
      const ms = R.played.filter(m => m.home === t || m.away === t).slice().reverse();
      for (const m of ms) {
        if (vals.length >= 38) break;
        const side = m.home === t ? 'home' : 'away', opp = side === 'home' ? 'away' : 'home';
        const useXg = R.season.hasXg;
        vals.push(useXg ? m.stats[side].xg - m.stats[opp].xg : m.score[side] - m.score[opp]);
      }
    }
    const k = 6, prior = vals.length < 10 ? -0.5 : 0;
    out[t] = { rating: r2((vals.reduce((a, b) => a + b, 0) + k * prior) / (vals.length + k)), matches: vals.length };
  });
  return out;
}
